# configuration file /etc/kvmd/nginx/nginx.conf:
user www-data;
worker_processes 1;
worker_shutdown_timeout 2s;
pid /run/nginx.pid;
error_log /var/log/nginx/error.log warn;
events { worker_connections 128; }
http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    access_log /var/log/nginx/access.log combined;
    sendfile on;
    tcp_nodelay on;
    keepalive_timeout 10;
    client_max_body_size 4k;
    proxy_http_version 1.1;
    proxy_cookie_flags auth_token secure httponly samesite=strict;
    upstream kvmd { server unix:/run/kvmd/api/kvmd.sock fail_timeout=0s max_fails=0; }
    upstream ustreamer { server unix:/run/kvmd/ustreamer/ustreamer.sock fail_timeout=0s max_fails=0; }
    server {
        listen 192.168.88.2:443 ssl;
        server_name blikvm-v4.lab 192.168.88.2;
        ssl_protocols TLSv1.2 TLSv1.3;
        ssl_certificate /etc/kvmd/nginx/ssl/server.crt;
        ssl_certificate_key /etc/kvmd/nginx/ssl/server.key;
        absolute_redirect off;
        root /usr/share/kvmd/web;
        index index.html;
        auth_request /auth_check;
        location = /auth_check {
            internal;
            proxy_pass http://kvmd/auth/check;
            proxy_pass_request_body off;
            proxy_set_header Content-Length "";
            auth_request off;
        }
        location / {
            error_page 401 403 = @login;
            include /etc/kvmd/nginx/loc-nocache.conf;
        }
        location @login { return 302 /login; }
        location /login {
            auth_request off;
            include /etc/kvmd/nginx/loc-nocache.conf;
        }
        location /share/ {
            auth_request off;
            include /etc/kvmd/nginx/loc-nocache.conf;
        }
        location = /share/css/user.css { auth_request off; alias /etc/kvmd/web.css; }
        location = /favicon.ico { auth_request off; }
        location = /robots.txt { auth_request off; }
        location = /streamer {
            proxy_pass http://ustreamer/;
            include /etc/kvmd/nginx/loc-proxy.conf;
            include /etc/kvmd/nginx/loc-nobuffering.conf;
        }
        location /streamer/ {
            proxy_pass http://ustreamer/;
            include /etc/kvmd/nginx/loc-proxy.conf;
            include /etc/kvmd/nginx/loc-nobuffering.conf;
        }
        location = /api/ws {
            proxy_pass http://kvmd/ws;
            include /etc/kvmd/nginx/loc-proxy.conf;
            include /etc/kvmd/nginx/loc-websocket.conf;
            auth_request off;
        }
        location /api/ {
            proxy_pass http://kvmd/;
            include /etc/kvmd/nginx/loc-proxy.conf;
            auth_request off;
        }
    }
}

