# configuration file /etc/kvmd/nginx/loc-nocache.conf:
# Do not edit this file

add_header Cache-Control "no-store, no-cache, must-revalidate, proxy-revalidate, pre-check=0, post-check=0, max-age=0";
expires -1;

# configuration file /etc/kvmd/nginx/loc-proxy.conf:
# Do not edit this file

proxy_set_header Host $host;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Scheme $scheme;
proxy_set_header X-Forwarded-Proto $scheme;
proxy_set_header X-Forwarded-Port $server_port;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

# configuration file /etc/kvmd/nginx/loc-nobuffering.conf:
# Do not edit this file

postpone_output 0;
proxy_buffering off;
proxy_ignore_headers X-Accel-Buffering;

# configuration file /etc/kvmd/nginx/loc-websocket.conf:
# Do not edit this file

proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection "upgrade";
proxy_connect_timeout 7d;
proxy_send_timeout 7d;
proxy_read_timeout 7d;

